@dataclass
class RuleResult:
    category: str | None        # 매칭된 카테고리, 매칭 없으면 None
    confidence: float           # 0.0 또는 0.85~0.98
    matched_keywords: list[str] # 매칭된 키워드들
    explanation: str            # 사람이 읽을 사유

    @property
    def is_confident(self) -> bool:
        return self.category is not None


def _normalize(name: str) -> str:
    """파일명 정규화 — 확장자 제거, 연속 공백/언더스코어 정리."""
    # 확장자 제거
    name = re.sub(r"\.[A-Za-z0-9]{2,5}$", "", name)
    # 언더스코어/하이픈을 공백처럼 처리 (키워드 매칭이 잘 되도록)
    name = re.sub(r"[_]+", " ", name)
    return name


def classify_by_filename(filename: str, conservative: bool = False) -> RuleResult:
    """파일명으로 룰 매칭.

    Parameters
    ----------
    conservative : bool
        True이면 RULES_CONSERVATIVE를 사용 — Test.zip 파일명을 보고 추가한
        키워드가 제외된 보수적 룰셋. overfitting 진단용.

    Returns
    -------
    RuleResult
        category가 None이면 룰 매칭 실패 → 의미기반 단계로 위임.
    """
    norm = _normalize(filename)
    rules = RULES_CONSERVATIVE if conservative else RULES

    scores: dict[str, list[str]] = {}
    for category, keywords in rules:
        if not keywords:
            continue
        matched: list[str] = []
        for kw in keywords:
            if kw in norm:
                matched.append(kw)
        if matched:
            scores[category] = matched

    if not scores:
        return RuleResult(
            category=None,
            confidence=0.0,
            matched_keywords=[],
            explanation="파일명에서 룰 키워드 매칭 실패 → 의미기반 단계로 위임",
        )

    # 매칭 키워드 총 글자 수가 가장 큰 카테고리
    best_cat, best_matched = max(
        scores.items(),
        key=lambda x: (sum(len(k) for k in x[1]), len(x[1])),
    )

    # 신뢰도: 매칭 키워드 수가 많을수록 ↑, 단일 매칭이라도 0.90 보장
    n = len(best_matched)
    confidence = min(0.98, 0.90 + 0.02 * (n - 1))

    # 다른 카테고리에도 매칭이 있었다면 약간 페널티 (모호함)
    if len(scores) > 1:
        confidence = max(0.85, confidence - 0.05)

    explanation = (
        f"파일명에서 키워드 {n}개 매칭: {', '.join(best_matched)}"
    )
    if len(scores) > 1:
        others = ", ".join(
            f"{c}({len(m)})" for c, m in scores.items() if c != best_cat
        )
        explanation += f". 다른 후보도 일부 매칭됨: {others}"

    return RuleResult(
        category=best_cat,
        confidence=confidence,
        matched_keywords=best_matched,
        explanation=explanation,
    )
